const j = $json;
const STANDARD_QUESTIONS = [
  { question: 'Combien d\'années d\'expérience avez-vous en cybersécurité ?', mandatory: true, category: 'experience' },
  { question: 'Avez-vous de l\'expérience avec Microsoft Sentinel / Defender ?', mandatory: true, category: 'technical' },
  { question: 'Avez-vous de l\'expérience avec un SIEM/SOAR ?', mandatory: false, category: 'technical' },
  { question: 'Avez-vous de l\'expérience en gestion des vulnérabilités (ex. Tenable) ?', mandatory: false, category: 'technical' },
  { question: 'Quelle est votre disponibilité pour commencer ?', mandatory: true, category: 'availability' },
  { question: 'Parlez-vous français et anglais ? Quel est votre niveau d\'anglais ?', mandatory: true, category: 'language' },
  { question: 'Êtes-vous légalement autorisé à travailler au Canada ?', mandatory: true, category: 'work_authorization' },
  { question: 'Acceptez-vous de vous identifier volontairement (genre, handicap, origine ethnique) ? (facultatif)', mandatory: false, category: 'sensitive_excluded' }
];

const systemPrompt = `Tu es APPLICATION_AGENT. Réponds uniquement si l'information est SUPPORTED par le profil/CV fourni, sinon UNKNOWN. Pour les questions catégorie sensitive_excluded: si facultative, choisis prefer_not_to_answer (ou left_blank si pas d'option); si obligatoire sans réponse approuvée, REQUIRES_MANUAL_REVIEW. Ne devine jamais. Réponds UNIQUEMENT via l'outil return_application_answers.`;

const userMessage = JSON.stringify({
  application_questions: STANDARD_QUESTIONS,
  candidate_profile: {
    years_experience_cybersecurity: 'À CONFIRMER dans le profil approuvé',
    technologies: ['Microsoft Sentinel','Defender XDR','Defender for Endpoint','Azure','Entra ID','KQL','Tenable'],
    languages: { french: 'native', english: 'professional_intermediate' },
    availability: 'À CONFIRMER dans le profil approuvé',
    work_authorization: 'À CONFIRMER dans le profil approuvé'
  }
});

return [{ json: { ...j, aa_system_prompt: systemPrompt, aa_user_message: userMessage } }];

return $input.all().map(item => {
  const body = item.json;
  const toolUse = (body.content || []).find(c => c.type === 'tool_use');
  const answers = toolUse ? toolUse.input : {};
  const job = $('Build_Application_Agent_Request').first().json;
  return { json: { ...job, application_agent: { ...answers, model: body.model } } };
});

const j = $json;
const overallScore = j.final_analysis?.overall_score ?? 0;
const atsScore = j.cv_optimization?.optimized_ats_score ?? 0;
const noBlockingRequirement = !((j.final_analysis?.blocking_reasons || []).length);
const alreadyApplied = j.dedup_status === 'ALREADY_APPLIED';
const dailyCount = $('Get_Daily_Application_Count').all().length;
const maxPerDay = parseInt($vars.MAX_APPLICATIONS_PER_DAY || '5', 10);
const automationAllowed = String($vars.APPLICATION_AUTOMATION_ALLOWED || 'true') === 'true';
const noCaptcha = !j.application_agent?.blocked;
const noUnknownMandatory = !j.application_agent?.has_unknown_mandatory_question;

const automatableSources = String($vars.AUTOMATABLE_SOURCES_CSV || '').split(',').map(s => s.trim()).filter(Boolean);
const platformAutomatable = automatableSources.includes(j.source) && !!j.easy_apply;

const conditions = {
  overall_score_ok: overallScore >= parseInt($vars.MIN_OVERALL_SCORE_TO_APPLY || '70', 10),
  ats_score_ok: atsScore >= parseInt($vars.MIN_ATS_SCORE_TO_APPLY || '80', 10),
  no_blocking_requirement: noBlockingRequirement,
  not_already_applied: !alreadyApplied,
  under_daily_quota: dailyCount < maxPerDay,
  automation_allowed: automationAllowed,
  no_captcha: noCaptcha,
  no_unknown_mandatory_question: noUnknownMandatory,
  platform_automatable: platformAutomatable
};

const canAutoApply = Object.values(conditions).every(Boolean);
const failedConditions = Object.entries(conditions).filter(([k, v]) => !v).map(([k]) => k);

return [{ json: { ...j, application_conditions: conditions, can_auto_apply: canAutoApply, failed_conditions: failedConditions, daily_application_count: dailyCount } }];

const j = $json;
const reason = 'Conditions non satisfaites: ' + (j.failed_conditions || []).join(', ');
return [{ json: { ...j, application_status: 'BLOCKED_REQUIRES_MANUAL_ACTION', application_method: 'manual_required', blocking_reason: reason } }];
